package com.learnagent.memory;

import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class MemoryReviewService{private final FlashcardRepository cards;private final FlashcardReviewStateRepository states;private final FlashcardReviewLogRepository logs;private final MemoryReviewSessionRepository sessions;private final FlashcardService flashcards;private final FsrsSchedulerService fsrs;private final KnowledgeGraphService graph;private final Clock clock;private final ZoneId zone;public MemoryReviewService(FlashcardRepository cards,FlashcardReviewStateRepository states,FlashcardReviewLogRepository logs,MemoryReviewSessionRepository sessions,FlashcardService flashcards,FsrsSchedulerService fsrs,KnowledgeGraphService graph,Clock clock,@Value("${learnagent.time-zone:Asia/Shanghai}")String zone){this.cards=cards;this.states=states;this.logs=logs;this.sessions=sessions;this.flashcards=flashcards;this.fsrs=fsrs;this.graph=graph;this.clock=clock;this.zone=ZoneId.of(zone);}@Transactional public List<MemoryDtos.CardView>due(UUID courseId){Instant now=clock.instant();List<Candidate>values=new ArrayList<>();for(FlashcardReviewState state:states.findByDueAtLessThanEqualOrderByRetrievabilityAscDueAtAsc(now)){Flashcard card=cards.findById(state.getCardId()).orElse(null);if(card==null||card.getStatus()!=FlashcardStatus.ACTIVE||(courseId!=null&&!courseId.equals(card.getCourseId())))continue;double retrieval=fsrs.retrievability(state.getFsrsCardJson(),now);state.refreshRetrievability(retrieval);values.add(new Candidate(card,retrieval,state.getDueAt()));}return values.stream().sorted(Comparator.comparingDouble(Candidate::retrievability).thenComparing(Candidate::due)).limit(20).map(value->flashcards.get(value.card().getId())).toList();}@Transactional public MemoryDtos.ReviewSessionView start(MemoryDtos.StartReviewRequest request){LocalDate today=LocalDate.now(zone);Optional<MemoryReviewSession>existing=sessions.findFirstByReviewDateAndStatusOrderByStartedAtDesc(today,MemoryReviewSessionStatus.ACTIVE);if(existing.isPresent())return view(existing.get(),request.courseId());List<MemoryDtos.CardView>due=due(request.courseId());MemoryReviewSession session=sessions.save(new MemoryReviewSession(today,due.size()));if(due.isEmpty())session.complete();return view(session,request.courseId());}@Transactional public MemoryDtos.ReviewResult review(UUID sessionId,UUID cardId,MemoryDtos.ReviewRequest request){MemoryReviewSession session=sessions.findById(sessionId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Memory review session not found."));if(session.getStatus()!=MemoryReviewSessionStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Memory review session is already complete.");Flashcard card=cards.findById(cardId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flashcard not found."));if(card.getStatus()!=FlashcardStatus.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active flashcards can be reviewed.");FlashcardReviewState state=states.findById(cardId).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Flashcard has no FSRS state."));Instant now=clock.instant(),beforeDue=state.getDueAt();int seconds=Math.max(0,Math.min(request.durationSeconds()==null?0:request.durationSeconds(),900));var scheduled=fsrs.schedule(state.getFsrsCardJson(),request.rating(),now,seconds);state.update(scheduled.afterJson(),scheduled.difficulty(),scheduled.stability(),scheduled.retrievability(),scheduled.due(),now,request.rating()==MemoryRating.AGAIN);logs.save(new FlashcardReviewLog(cardId,sessionId,request.rating(),now,seconds,beforeDue,scheduled.due(),scheduled.scheduledDays(),scheduled.beforeJson(),scheduled.afterJson()));session.record(request.rating(),seconds);graph.refresh(card.getCourseId(),card.getKnowledgePoint());return new MemoryDtos.ReviewResult(flashcards.get(cardId),scheduled.due(),scheduled.scheduledDays(),scheduled.retrievability(),view(session,card.getCourseId()));}@Transactional(readOnly=true)public MemoryDtos.MemoryStatistics statistics(){Instant now=clock.instant();ZonedDateTime zoned=now.atZone(zone);Instant start=zoned.toLocalDate().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)).atStartOfDay(zone).toInstant();Instant end=start.atZone(zone).plusWeeks(1).toInstant();List<FlashcardReviewLog>week=logs.findByReviewedAtGreaterThanEqualAndReviewedAtLessThan(start,end);long success=week.stream().filter(log->log.getRating()!=MemoryRating.AGAIN).count();Map<MemoryRating,Long>distribution=new EnumMap<>(MemoryRating.class);for(MemoryRating rating:MemoryRating.values())distribution.put(rating,week.stream().filter(log->log.getRating()==rating).count());int seconds=week.stream().mapToInt(FlashcardReviewLog::getDurationSeconds).sum();return new MemoryDtos.MemoryStatistics(cards.countByStatus(FlashcardStatus.ACTIVE),cards.countByStatus(FlashcardStatus.CANDIDATE),states.findByDueAtLessThanEqualOrderByRetrievabilityAscDueAtAsc(now).stream().filter(state->cards.findById(state.getCardId()).map(card->card.getStatus()==FlashcardStatus.ACTIVE).orElse(false)).count(),week.isEmpty()?0:(double)success/week.size(),week.size(),seconds,distribution,graph.highRisk(5));}@Transactional(readOnly=true)public MemoryDtos.ReviewSessionView getSession(UUID id){return view(sessions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Memory review session not found.")),null);}private MemoryDtos.ReviewSessionView view(MemoryReviewSession session,UUID courseId){return new MemoryDtos.ReviewSessionView(session.getId(),session.getReviewDate(),session.getStatus(),session.getPlannedCount(),session.getReviewedCount(),session.getCorrectCount(),session.getElapsedSeconds(),session.getStatus()==MemoryReviewSessionStatus.ACTIVE?due(courseId):List.of());}private record Candidate(Flashcard card,double retrievability,Instant due){} }
